
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_camy_blyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_camy_blyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.344385128756787e+00, -3.278672263329693e+00, -3.186631746345292e+00, -3.059211739460098e+00, -2.885742298404771e+00, -2.655165206111552e+00, -2.358902570830530e+00, -1.995836988247272e+00, -1.578279898849262e+00, -1.133295704213521e+00, -7.011010776456816e-01, -4.511757211255311e-01, -3.798568740295037e-01, -2.941964114325472e-01, -1.794488573461085e-01, -7.011124852043032e-02, -8.138698026574669e-03, -1.423617995019291e-03, -7.844485963606984e-05, -1.755113711893107e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


